-static int MimeInlineText_rot13_line(MimeObject* obj, char* line,
-                                     int32_t length) {
-  unsigned char *s, *end;
-  PR_ASSERT(line);
-  if (!line) return -1;
-  s = (unsigned char*)line;
-  end = s + length;
-  while (s < end) {
-    *s = MimeInlineText_rot13_table[*s];
-    s++;
-  }
-  return 0;
-}
